`,f.jsx(o.em,{children:"Grid Composables Screen"})]})]})}function E1(u={}){const{wrapper:o}=u.components||{};return o?f.jsx(o,{...u,children:f.jsx(wh,{...u})}):wh(u)}const um=Object.freeze(Object.defineProperty({__proto__:null,default:E1,frontmatter:w1},Symbol.toStringTag,{value:"Module"})),j1={title:"Kotlin Fundamentals & Adding Functionality",date:"8/31/2025",wordCount:495};function Eh(u){const o={a:"a",code:"code",em:"em",img:"img",li:"li",p:"p",ul:"ul",...u.components};return f.jsxs(f.Fragment,{children:[f.jsxs(o.p,{children:["This week, I kept following the ",f.jsx(o.a,{href:"https://developer.android.com/courses/android-basics-compose/course",children:"Android Basics with Compose"})," course from last week, this time working on Unit 2. I took some time to focus more on Kotlin itself and how it compares to what I already know from JavaScript. Since Kotlin will be my main language for Android development, I wanted to really understand its quirks and how it interacts with the designs created with Compose."]}),`
